CREATE TABLE IF NOT EXISTS schema_migrations(version TEXT PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, external_subject TEXT UNIQUE, display_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY, name TEXT NOT NULL, environment TEXT NOT NULL CHECK(environment IN ('cloud','self_hosted')), criticality TEXT NOT NULL DEFAULT 'normal', owner_user_id TEXT REFERENCES users(id), rpo_seconds INTEGER NOT NULL DEFAULT 86400, rto_seconds INTEGER NOT NULL DEFAULT 28800, created_at TEXT NOT NULL, disabled_at TEXT);
CREATE TABLE IF NOT EXISTS project_members(project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('viewer','operator','administrator','recovery_approver')), PRIMARY KEY(project_id,user_id,role));
CREATE TABLE IF NOT EXISTS connections(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), connection_type TEXT NOT NULL, endpoint_redacted TEXT NOT NULL, secret_ref TEXT NOT NULL, tls_mode TEXT NOT NULL, last_tested_at TEXT);
CREATE TABLE IF NOT EXISTS capability_assessments(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), component TEXT NOT NULL, capability TEXT NOT NULL CHECK(capability IN ('automated','manual','unsupported','unknown')), evidence_json TEXT NOT NULL, assessed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS component_inventory(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), component TEXT NOT NULL, resource_key TEXT NOT NULL, metadata_json TEXT NOT NULL, discovered_at TEXT NOT NULL, UNIQUE(project_id,component,resource_key));
CREATE TABLE IF NOT EXISTS backup_policies(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), name TEXT NOT NULL, schedule_expression TEXT NOT NULL, timezone TEXT NOT NULL, retention_json TEXT NOT NULL, component_policy_json TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)));
CREATE TABLE IF NOT EXISTS backup_jobs(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), policy_id TEXT REFERENCES backup_policies(id), recovery_set_id TEXT, state TEXT NOT NULL CHECK(state IN ('queued','running','uploading','verifying','completed','partial_failure','failed','cancelled')), idempotency_key TEXT, started_at TEXT, finished_at TEXT, error_code TEXT, UNIQUE(project_id,idempotency_key));
CREATE TABLE IF NOT EXISTS recovery_sets(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), state TEXT NOT NULL CHECK(state IN ('collecting','staged','published','conditional','failed')), started_at TEXT NOT NULL, completed_at TEXT, manifest_uri TEXT, manifest_sha256 TEXT, manifest_signature_ref TEXT, consistency_start_at TEXT, consistency_end_at TEXT, readiness TEXT NOT NULL DEFAULT 'unknown' CHECK(readiness IN ('recoverable','manual_steps','at_risk','unknown')));
CREATE TABLE IF NOT EXISTS component_archives(id TEXT PRIMARY KEY, recovery_set_id TEXT NOT NULL REFERENCES recovery_sets(id), component TEXT NOT NULL, capture_state TEXT NOT NULL, capture_started_at TEXT, capture_ended_at TEXT, content_sha256 TEXT, encrypted_bytes INTEGER CHECK(encrypted_bytes>=0), encryption_envelope_json TEXT, details_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS storage_destinations(id TEXT PRIMARY KEY, name TEXT NOT NULL, provider TEXT NOT NULL CHECK(provider IN ('local','s3','azure','google_drive','onedrive')), config_json TEXT NOT NULL, secret_ref TEXT, enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS archive_replicas(id TEXT PRIMARY KEY, archive_id TEXT NOT NULL REFERENCES component_archives(id), destination_id TEXT NOT NULL REFERENCES storage_destinations(id), object_key TEXT NOT NULL, state TEXT NOT NULL, checksum TEXT, verified_at TEXT, retain_until TEXT, protected INTEGER NOT NULL DEFAULT 0, UNIQUE(archive_id,destination_id,object_key));
CREATE TABLE IF NOT EXISTS verification_runs(id TEXT PRIMARY KEY, recovery_set_id TEXT NOT NULL REFERENCES recovery_sets(id), kind TEXT NOT NULL CHECK(kind IN ('integrity','restore_drill')), state TEXT NOT NULL, started_at TEXT NOT NULL, finished_at TEXT, evidence_uri TEXT);
CREATE TABLE IF NOT EXISTS restore_jobs(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), recovery_set_id TEXT NOT NULL REFERENCES recovery_sets(id), requester_id TEXT NOT NULL REFERENCES users(id), target_fingerprint TEXT NOT NULL, plan_digest TEXT NOT NULL, scope_json TEXT NOT NULL, state TEXT NOT NULL, created_at TEXT NOT NULL, finished_at TEXT);
CREATE TABLE IF NOT EXISTS restore_steps(id TEXT PRIMARY KEY, restore_job_id TEXT NOT NULL REFERENCES restore_jobs(id), ordinal INTEGER NOT NULL, component TEXT NOT NULL, state TEXT NOT NULL, evidence_json TEXT NOT NULL DEFAULT '{}', UNIQUE(restore_job_id,ordinal));
CREATE TABLE IF NOT EXISTS approval_requests(id TEXT PRIMARY KEY, restore_job_id TEXT NOT NULL REFERENCES restore_jobs(id), approver_id TEXT REFERENCES users(id), requester_id TEXT NOT NULL REFERENCES users(id), plan_digest TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','approved','rejected','expired')), expires_at TEXT NOT NULL, decided_at TEXT);
CREATE TABLE IF NOT EXISTS audit_events(id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id), actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, target_type TEXT, target_id TEXT, result TEXT NOT NULL, request_id TEXT NOT NULL, event_at TEXT NOT NULL, previous_hash TEXT, event_hash TEXT NOT NULL, metadata_redacted_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id), kind TEXT NOT NULL, severity TEXT NOT NULL, state TEXT NOT NULL, created_at TEXT NOT NULL, delivered_at TEXT);
CREATE TABLE IF NOT EXISTS application_dependencies(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), name TEXT NOT NULL, dependency_type TEXT NOT NULL, recovery_notes TEXT NOT NULL DEFAULT '', secret_ref TEXT);
CREATE INDEX IF NOT EXISTS idx_jobs_project_state ON backup_jobs(project_id,state,started_at);
CREATE INDEX IF NOT EXISTS idx_sets_project_time ON recovery_sets(project_id,started_at DESC);
CREATE INDEX IF NOT EXISTS idx_archives_set ON component_archives(recovery_set_id);
CREATE INDEX IF NOT EXISTS idx_audit_project_time ON audit_events(project_id,event_at DESC);
CREATE INDEX IF NOT EXISTS idx_replica_state ON archive_replicas(destination_id,state);
